from pathlib import Path
from PIL import Image,ImageDraw,ImageFilter
import cv2,numpy as np,json
R=Path(__file__).resolve().parents[4];P=R/'work/first-day-anime-test/faithful';source=Image.open(P/'leap-bare-cutout.png').convert('RGBA');white=Image.open(P/'leap-camera/white.png');original=Image.open(P/'leap-pair-cutout.png');off=((white.width-original.width)//2,(white.height-original.height)//2);canvas=Image.new('RGBA',white.size);canvas.alpha_composite(source,off);cap=cv2.VideoCapture(str(P/'leap-camera/leap-camera.mp4'));cap.set(1,123);ok,frame=cap.read();a=cv2.cvtColor(np.array(white),cv2.COLOR_RGB2GRAY);b=cv2.cvtColor(frame,cv2.COLOR_BGR2GRAY);s=cv2.SIFT_create();ka,da=s.detectAndCompute(a,None);kb,db=s.detectAndCompute(b,None);pairs=cv2.BFMatcher().knnMatch(da,db,k=2);good=[m for m,n in pairs if m.distance<.68*n.distance];pa=np.float32([ka[m.queryIdx].pt for m in good]);pb=np.float32([kb[m.trainIdx].pt for m in good]);M,mask=cv2.estimateAffinePartial2D(pa,pb,method=cv2.RANSAC,ransacReprojThreshold=4);assert M is not None and mask.sum()>15
arr=cv2.warpAffine(np.array(canvas),M,(frame.shape[1],frame.shape[0]),flags=cv2.INTER_LANCZOS4);Image.fromarray(arr).save(P/'leap-bare-registered.png')
mat=Image.new('L',white.size);d=ImageDraw.Draw(mat)
for box in [(250,570,620,1000),(805,670,1090,1015)]:d.rounded_rectangle((box[0]+off[0],box[1]+off[1],box[2]+off[0],box[3]+off[1]),radius=20,fill=255)
mat=mat.filter(ImageFilter.GaussianBlur(6));m=cv2.warpAffine(np.array(mat),M,(frame.shape[1],frame.shape[0]));Image.fromarray(m).save(P/'leap-foot-regions.png');(P/'leap-bare-registration.json').write_text(json.dumps({'method':'SIFT/RANSAC similarity; replacement confined to shoe/lower-leg masks','inliers':int(mask.sum()),'matrix':M.tolist()},indent=2));print(int(mask.sum()),M)
